def find_photo():
    """Use the first matching photo committed beside app.py."""
    root = Path(__file__).resolve().parent
    extensions = {".jpg", ".jpeg", ".png", ".webp", ".gif"}
    photos = sorted((p for p in root.iterdir() if p.is_file() and p.suffix.lower() in extensions),
                    key=lambda p: (0 if p.stem.lower() in {"sanjana", "our_photo", "photo", "us", "birthday_photo"} else 1, p.name.lower()))
    if not photos:
        return None
    image = photos[0]
    mime = mimetypes.guess_type(image.name)[0] or "image/jpeg"
    return f"data:{mime};base64,{base64.b64encode(image.read_bytes()).decode('ascii')}"


